def rectify_errors_by_accounting_stage(error_cases):
    rectification_journal = []

    for case in error_cases:
        stage = case['stage']
        err_type = case['error_type']
        amt = case['amount']
        details = case['details']

        if stage == 'STAGE_1_PRE_TRIAL_BALANCE':
            rectification_journal.append({
                'stage': stage,
                'method': 'Direct Ledger Account Correction / Explanatory Note (No Suspense Account Used)',
                'amount': amt,
                'details': details,
                'journal_entry': case.get('direct_fix', 'Adjust account folio directly')
            })
        elif stage == 'STAGE_2_POST_TB_PRE_FINAL_ACCOUNTS':
            rectification_journal.append({
                'stage': stage,
                'method': 'Rectification Journal Entry via Suspense Account',
                'amount': amt,
                'details': details,
                'journal_entry': case.get('suspense_entry', 'Debit/Credit Suspense Account')
            })
        elif stage == 'STAGE_3_POST_FINAL_ACCOUNTS_NEXT_YEAR':
            rectification_journal.append({
                'stage': stage,
                'method': 'Prior Period Rectification via Profit & Loss Adjustment Account',
                'amount': amt,
                'details': details,
                'journal_entry': case.get('pnl_adj_entry', 'Debit/Credit P&L Adjustment Account')
            })

    return {
        'total_cases_rectified': len(rectification_journal),
        'rectifications': rectification_journal
    }

