def manage_suspense_account_lifecycle(initial_tb_imbalance, rectification_entries):
    # If debits exceed credits in TB, Suspense carries a Credit balance (-ve) to balance
    # If credits exceed debits in TB, Suspense carries a Debit balance (+ve) to balance
    suspense_balance = initial_tb_imbalance
    audit_trail = []

    for entry in rectification_entries:
        desc = entry['description']
        susp_effect = entry['suspense_effect']  # 'DR' reduces credit balance, 'CR' reduces debit balance
        amt = entry['amount']

        if susp_effect == 'DR':
            suspense_balance -= amt
        elif susp_effect == 'CR':
            suspense_balance += amt

        audit_trail.append((desc, susp_effect, amt, round(suspense_balance, 2)))

    is_cleared = abs(round(suspense_balance, 2)) < 0.01

    return {
        'initial_suspense_opened': initial_tb_imbalance,
        'final_suspense_closing': round(suspense_balance, 2),
        'is_suspense_fully_liquidated': is_cleared,
        'audit_trail': audit_trail
    }

